def f(N: int, M: int, edges: List[Tuple[int, int]]) -> int:
    parent = list(range(N+1))
    size = [1] * (N+1)

    def find(u):
        if parent[u]!= u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        ru, rv = find(u), find(v)
